// HasTenantSubscription applies the HasEdge predicate on the "tenant_subscription" edge.
func HasTenantSubscription() predicate.SupportAgreement {
	return predicate.SupportAgreement(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, TenantSubscriptionTable, TenantSubscriptionColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasTenantSubscriptionWith applies the HasEdge predicate on the "tenant_subscription" edge with a given conditions (other predicates).
func HasTenantSubscriptionWith(preds ...predicate.TenantSubscription) predicate.SupportAgreement {
	return predicate.SupportAgreement(func(s *sql.Selector) {
		step := newTenantSubscriptionStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

